#import <Foundation/Foundation.h>
#import <Metal/Metal.h>
#include <cstdio>
int main(int argc,const char**argv){@autoreleasepool{
 if(argc!=4){fprintf(stderr,"usage: driver shader input output\n");return 1;}NSError* err=nil;NSString* source=[NSString stringWithContentsOfFile:[NSString stringWithUTF8String:argv[1]] encoding:NSUTF8StringEncoding error:&err];NSData* input=[NSData dataWithContentsOfFile:[NSString stringWithUTF8String:argv[2]]];if(!source||!input||input.length!=472){fprintf(stderr,"invalid shader or input\n");return 2;}
 id<MTLDevice> dev=MTLCreateSystemDefaultDevice();if(!dev)return 3;MTLCompileOptions* opt=[MTLCompileOptions new];opt.fastMathEnabled=NO;id<MTLLibrary> lib=[dev newLibraryWithSource:source options:opt error:&err];if(!lib){fprintf(stderr,"shader: %s\n",err.localizedDescription.UTF8String);return 4;}id<MTLFunction> fn=[lib newFunctionWithName:@"rod_modal"];id<MTLComputePipelineState> pipe=[dev newComputePipelineStateWithFunction:fn error:&err];if(!pipe){fprintf(stderr,"pipeline: %s\n",err.localizedDescription.UTF8String);return 5;}
 id<MTLBuffer> ib=[dev newBufferWithBytes:input.bytes length:input.length options:MTLResourceStorageModeShared];id<MTLBuffer> ob=[dev newBufferWithLength:80*18*sizeof(float) options:MTLResourceStorageModeShared];id<MTLBuffer> sb=[dev newBufferWithLength:sizeof(uint32_t) options:MTLResourceStorageModeShared];id<MTLCommandBuffer> cb=[[dev newCommandQueue] commandBuffer];id<MTLComputeCommandEncoder> enc=[cb computeCommandEncoder];[enc setComputePipelineState:pipe];[enc setBuffer:ib offset:0 atIndex:0];[enc setBuffer:ob offset:0 atIndex:1];[enc setBuffer:sb offset:0 atIndex:2];[enc dispatchThreads:MTLSizeMake(1,1,1) threadsPerThreadgroup:MTLSizeMake(1,1,1)];[enc endEncoding];[cb commit];[cb waitUntilCompleted];if(cb.status!=MTLCommandBufferStatusCompleted){fprintf(stderr,"command buffer: %s\n",cb.error.localizedDescription.UTF8String);return 6;}if(*(uint32_t*)sb.contents!=0){fprintf(stderr,"GPU reported invalid result\n");return 8;}NSData* result=[NSData dataWithBytes:ob.contents length:80*18*sizeof(float)];if(![result writeToFile:[NSString stringWithUTF8String:argv[3]] atomically:YES])return 7;printf("{\"device\":\"%s\",\"fast_math\":false,\"steps\":80,\"status\":0}\n",dev.name.UTF8String);return 0;
}}
